# coding: utf-8
"""Build two standalone offline HTML pages from the shared design simulator."""
from pathlib import Path
from html import escape
root=Path(__file__).resolve().parents[2]
source=Path(__file__).resolve().parent
css=(source/'style.css').read_text()
model=(source/'simulation.js').read_text()
view=(source/'view.js').read_text()
controls='''<div class="controls"><label>场景 <select id="scenario" aria-label="选择演示场景"></select></label><button id="previous">上一步</button><button class="primary" id="next">下一步</button><button id="play">自动播放</button><button id="reset">重置</button><button id="end">查看结局</button><b id="position" aria-live="polite"></b><input class="seek" id="seek" type="range" min="0" value="0" aria-label="跳转演示步骤"></div><p id="scenario-note"></p>'''
summary='''<div class="metrics"><div class="metric">读取游标<b id="read"></b><small>已从老表取到的位置</small></div><div class="metric">安全游标<b id="safe"></b><small>此前全部记录已处理</small></div><div class="metric">Memory 峰值<b id="peak"></b><small>按记录数限制</small></div><div class="metric">任务阶段<b id="task-status"></b></div><div class="metric">模型 DB 动作数<b id="db-total"></b><small>含 BEGIN / COMMIT 等</small></div></div><section class="event"><span id="action" class="pill"></span><h2 id="event-title"></h2><p id="event-detail"></p><p><strong>当前批：</strong><span id="batch"></span><br><strong>业务事务：</strong><span id="tx"></span></p></section>'''
dashboard='''<div class="split"><section class="panel"><h2>50 条老表记录</h2><div class="record-grid" id="grid"></div><p class="legend">灰：未读 · 蓝：加载/初比 · 黄：待复核/写入 · 绿：终态或已释放 · 红：失败/结果未知。这里只展示 50 个老表 ID；额外新表记录在下方 Memory 中展示。</p><h3>老表进度</h3><p id="old-phase"></p><h3>累计处理结果</h3><div id="results"></div><p class="legend">统计处理次数，包含反向扫描再次遇到记录；不是 50 个 ID 的互斥分组。终态回收不减少这些累计数。</p><h3>模型 DB 动作</h3><div id="io"></div><p class="legend">离线模型每个事件最多一个 DB 动作。不等同于真实网络包、生产 SQL 数或耗时；重试、锁等待和驱动行为不在模型内。</p></section><section class="panel"><h2>各新分片独立进度</h2><div id="shards" class="shards"></div><p class="legend">首次批量 Lookup 后，这些全表 Scan 游标仍是起点。反向扫描才逐个推进。</p><h3>最近步骤 · 单线程顺序</h3><ol id="log" class="log"></ol></section></div>
<section class="panel" style="margin-top:18px"><h2>Memory：总量与各状态计数</h2><div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center"><b style="font-size:28px"><span id="memory-total"></span> 条</b><label>分片 <select id="shard-filter"></select></label><label>记录筛选 <select id="state-filter"></select></label></div><div id="memory-counts"></div><p class="legend">总量和状态计数按所选 shard 统计；记录状态筛选仅筛下方明细，不改变这组统计。各状态计数之和 = 当前驻留总条数。两端数据都存在仍只算一条 key。</p><div class="table-scroll"><table><thead><tr><th>ID</th><th>shard</th><th>老表状态 / 值</th><th>新表状态 / 值</th><th>扫描来源</th><th>记录当前状态</th><th>当前差异</th></tr></thead><tbody id="memory-rows"></tbody></table></div></section>'''
contracts='''<h2>边界约定</h2><div class="lanes"><section><h3>有界与背压</h3><p>默认先扫描 50 条，Memory 上限也是 50；每页排空后才继续读。每 shard 的复核批最多 8 条、每条 INSERT 最多 4 条，UPDATE 每次 1 条。页尾不足阈值立即发批。</p></section><section><h3>同一事务重读并写入</h3><p>复核攒批在事务外。开启事务后按顺序重读老表、新分片，重新分类，批量插入与逐条更新，再提交。事务内不等下一扫描页来凑批。</p></section><section><h3>单线程 ≠ 数据库没有并发写</h3><p>框架单线程一次执行一个动作；业务仍可并发修改。真实适配器负责锁、隔离级别、唯一约束、版本校验及提交结果不确定时的恢复。实际 MySQL 适配器要求 Schema.KeyLess，并在锁定 IN 查询分块前排序；扫描/查询发现物理错片返回 ErrMisrouted，保留数据并停止。</p></section></div><p class="note">这是设计模拟，不调用数据库。Go 库（reconcile + mysqltable）已实现分片路由、分页扫描、按分片的批量复核与插入事务、逐步重试和进度回调；本页的逐 key 状态计数、检查点等仍是设计，尚未实现。页尾背压时必须立即处理已有尾批，不能只等计时器或未来页面来凑满。线上还需字节/参数预算、最大等待时间、检查点持久化及明确扫描边界。</p>'''
scenes='''<h2>可切换的情况</h2><ul><li>默认混合：5 个 shard 每片 10 条；相等、缺失、不同，以及每片 1 条额外记录。</li><li>全部相等 / 全部缺失 / 全部不同：观察哪些批次可以省略，以及插入如何拆批、更新如何逐条执行。</li><li>分片倾斜：40 条落入一个 shard；100 shard 稀疏：50 片有记录，其余为空。</li><li>复核前数据已同步：初比不同，事务重读后相等，不再更新。</li><li>完整查询失败、事务回滚、提交响应丢失、事务前取消：不误报成功、不提前推进安全游标。</li><li>只报警模式：无插入更新；50 条按 17 条分页：17 + 17 + 16，尾批照常执行。</li></ul>'''
def node(id,x,y,w,title,sub,cls=''):
 return f'<g data-node="{id}" class="{cls}" aria-label="{escape(title)}"><rect x="{x}" y="{y}" width="{w}" height="68" rx="10"/><text x="{x+16}" y="{y+27}" font-size="16" font-weight="650">{escape(title)}</text><text x="{x+16}" y="{y+50}" font-size="12">{escape(sub)}</text></g>'
def edge(points,label='',x=0,y=0,cls=''):
 return f'<path class="edge {cls}" d="{points}"/>'+(f'<text class="edge-label" x="{x}" y="{y}">{escape(label)}</text>' if label else '')
# Main path and branches. Rectangular arrows express synchronous calls, not workers.
def graph():
 items=[('init',30,'初始化任务','记录扫描边界、路由、上限'),('scanOld',130,'批量 SCAN 老表','一页 50；空页成功才是 EOF'),('route',230,'Memory 入批 / 按 shard 归组','逐 key 状态，当前页最多 50 条'),('lookup',330,'批量 Lookup 配对','完整结果：PRESENT / ABSENT'),('compare',430,'内存初比','相等释放；差异进入复核队列'),('queue',560,'当前 shard 复核批就绪','最多 8 条；页尾不足也发送'),('begin',700,'BEGIN','仅当前一个 shard 的一个复核批'),('readOld',800,'批量重读老表','同一事务，先老后新'),('readNew',900,'批量重读目标新分片','重新确认存在性及业务内容'),('classify',1000,'事务内重新分类','插入 / 更新 / 报警 / 跳过'),('commit',1330,'COMMIT / 等待确认','未确认前不得计成功或回收'),('done',1530,'结果确认完成','记录修复、跳过或可靠报警'),('release',1640,'回收已完成的记录','驻留状态计数扣除'),('checkpoint',1750,'当前扫描页全部分组已排空？','老页推进安全游标；反向页继续分片'),('scanNew',1860,'反向逐 shard 批量扫描新表','批量查老表；额外记录同样复核'),('finish',1980,'全部扫描与处理完成','Memory=0，无活动/未决事务')]
 out=['<svg viewBox="0 0 1120 2090" role="img" aria-labelledby="svg-title svg-desc"><title id="svg-title">单线程批量核对整体流转图</title><desc id="svg-desc">一条执行线依次扫描、按分片配对、内存比较、单事务复核和写入；明确错误、回滚、未知提交、反向扫描及循环分支。</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#718e9b"/></marker></defs>', '<rect x="340" y="675" width="750" height="735" rx="18" fill="#f1faf5" stroke="#95bba8" stroke-dasharray="6 5"/><text x="790" y="697" font-size="13">同一受保护业务事务</text>']
 ys=[v[1] for v in items]
 for i in range(len(items)-1):
  y1,y2=ys[i],ys[i+1]
  if i in [9,10,13,14]:continue
  out.append(edge(f'M 565 {y1+68} V {y2}'))
 out.extend([edge('M 755 1034 H 790 V 1254 H 810','仅更新：跳过 INSERT',790,1080),edge('M 1070 1254 H 1085 V 1205 H 935 V 1220','下一条待更新',875,1199,'loop'),edge('M 565 1068 V 1100 H 935 V 1115','有插入',745,1090),edge('M 935 1183 V 1220','然后逐条处理更新',965,1205),edge('M 935 1288 V 1364 H 755'),edge('M 565 1068 V 1330','没有写入 / 只报警 / 相等',575,1240),edge('M 565 1400 V 1530','提交已确认',578,1495)])
 # loops on right; next review and next shard return to queue / lookup.
 out.extend([edge('M 375 164 H 8 V 1894 H 375','老表空页成功 / EOF → 反向扫描',15,1820,'loop'),edge('M 755 464 H 785 V 1674 H 755','相等记录直接回收',794,520,'loop'),edge('M 755 1674 H 1098 V 590 H 755','当前 shard 还有复核批',820,1620,'loop'),edge('M 755 1784 H 1110 V 364 H 755','当前页还有 shard',820,1740,'loop'),edge('M 375 1784 H 325 V 164 H 375','老表还有页 → 下一页',210,1728,'loop'),edge('M 755 1784 H 1065 V 1894 H 755','反向页继续扫描',800,1808,'loop'),edge('M 565 1928 V 1980','全部分片 EOF 且已排空',575,1956),edge('M 755 1894 H 1080 V 364 H 755','反向页进入同一流水线',815,1840,'loop')])
 out.extend([edge('M 375 364 H 315 V 442 H 300','查询失败',240,350,'error'),edge('M 375 594 H 300','取消',310,580,'error'),edge('M 935 1254 H 1120 V 1135 H 300','事务内失败',18,1110,'error'),edge('M 375 1364 H 300','响应未知',290,1320,'error'),edge('M 170 1400 V 1450'),edge('M 300 1484 H 375 V 1564','确认最新结果后',305,1472,'loop')])
 for id,y,t,sub in items:out.append(node(id,375,y,380,t,sub,'tx' if 700<=y<=1330 else ''))
 out.extend([node('insert',810,1115,260,'批量 INSERT','无插入则跳过；每语句最多 4 条','tx'),node('update',810,1220,260,'逐条 UPDATE','每次 1 条；还有待更新则重复','tx'),node('failure',20,408,280,'失败停止','不将部分结果当缺失或成功','err'),node('cancel',20,560,280,'取消停止','无未决事务才能直接停止','err'),node('rollback',20,1135,280,'ROLLBACK → 失败','丢弃本事务暂存操作','err'),node('uncertain',20,1332,280,'提交结果未知','不推进安全游标、不盲重试','err'),node('confirm',20,1450,280,'重读 / 幂等恢复确认','此处展示有明确假设的恢复场景','err')])
 out.extend(['<text class="edge-label" x="20" y="195">老表 EOF 后转入反向扫描</text>','<text class="edge-label" x="20" y="515">一次仅一个节点执行；横排是分支，不是并发。</text>','<text class="edge-label" x="20" y="1945">反向页排空：继续同一分片或下一片。</text>','<text class="edge-label" x="20" y="2070">所有循环均串行；节点可点击跳到对应实际演示步骤。</text>','</svg>'])
 return ''.join(out)
flow_detail='''<h2>把三种状态分别看清</h2><div class="lanes"><section><h3>每张物理表</h3><p>未开始 → 扫描中 ↔ 缓存满暂停 → 扫描结束；查询失败是失败，不是 EOF。游标只被对应扫描推进。</p></section><section><h3>每个批次</h3><p>扫描页入内存 → 分 shard 配对 → 初比 → 复核批攒批 / 就绪 → 事务重读 / 分类 → 分操作写入 → 提交确认 → 排空。</p></section><section><h3>每条 key</h3><p>等待配对 → 等待初比 → 相等完成 / 候选待复核 → 事务复核中 → 待插入 / 待更新 / 待报警 / 跳过 → 等待提交 → 确认完成。</p></section></div>
<h2>单线程调度的具体判断</h2><ol class="contract"><li><strong>是否已有需要收尾的事务？</strong>有：继续读、分类、写入、提交或回滚；不去扫描下一页，不开启第二个事务。</li><li><strong>当前页是否仍有未完成 shard / 复核批？</strong>有：处理下一个复核批或分片，先排空当前页。</li><li><strong>当前页是否全部完成？</strong>是：回收内存，推进该页安全游标，再取下一页。</li><li><strong>老表是否真正 EOF？</strong>成功读取空页后才进入反向扫描；失败、取消不等于 EOF。</li><li><strong>反向扫描是否还有页 / shard？</strong>有：取一页新表数据，复用批量查询、比较与事务复核逻辑。</li><li><strong>所有扫描与批次结束且无未决结果？</strong>是：本轮完成；否则不能只因两边“扫描读完”就结束。</li></ol>
<p class="note">设计采用主动排空当前页的单线程调度，没有多个 worker，没有“扫描线程 + 写线程”同时跑。多个记录可以同时处于等待状态，但实际执行一次只推进一个批次动作。事务内的待插入 / 待更新是短暂分类，不是解锁后排长队。</p>
<h2>错误与安全游标</h2><ul><li>完整查询失败：不产生缺失结论；停止或显式重试完整查询。</li><li>事务内失败：先回滚再返回失败；当前批暂存数据不算修复成功。</li><li>提交结果未知：不能假定回滚，也不能假定成功；冻结相关进度，按业务协议重读并幂等确认。</li><li>取消发生在活动事务内：必须先处理事务的提交/回滚/未知结果；本演示的取消场景发生在 BEGIN 前。</li><li>老表已读到 50，但某片仍有候选：安全游标仍不推进到 50。进程重启后的检查点持久化由后续实现负责。</li></ul>'''
for mode,name,title,subtitle in [('batch','batch-scan-demo.html','扫描 50 条，逐 shard 看批次如何排空。','13 种场景 / 按记录观察 / 单线程批量推进'),('flow','single-thread-state-flow.html','单线程：一次只推进一个数据库动作。','具体状态流转 / 事务边界 / 循环、失败与恢复')]:
 header=f'<header><small>{subtitle}</small><h1>{title}</h1><p>离线设计演示 · 不连接数据库 · 非 Go 运行时监控</p><nav><a href="guide.html">原说明</a> · <a href="batch-scan-demo.html">50 条批量演示</a> · <a href="single-thread-state-flow.html">单线程整体图</a></nav></header>'
 if mode=='flow':main=header+controls+summary+'<h2>整体流转图 · 当前：<span id="flow-current"></span></h2><p id="flow-note">点击节点定位实际步骤；切换失败场景可查看对应分支。节点按顺序执行，图中横向分支不表示并发。</p><div class="flow-wrap">'+graph()+'</div>'+flow_detail+'<details><summary>展开当前步的 50 条记录、各分片及内存计数</summary>'+dashboard+'</details>'+contracts
 else:main=header+controls+summary+dashboard+scenes+contracts
 result='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+css+'</style></head><body data-view="'+mode+'"><main>'+main+'<footer>自包含 HTML · 源模型在 docs/visuals · 单线程模拟不保证单轮全局一致性 · 未包含真实数据库恢复实现</footer></main><script>'+model+'</script><script>'+view+'</script></body></html>'
 (root/name).write_text(result)
 print('Built',name)
